/* From Uiverse.io by benjimich - Tags: button, hover */
.__UIV_SCOPE__ .button {
  cursor: pointer;
  background: none;
  border: none;
  display: flex;
  flex-direction: column;
  width: 70px;
  gap: 4px;
}

.__UIV_SCOPE__ .button:hover {
  animation: move 2s infinite ease;
}

@keyframes move {
  0% {
    transform: translateX(0);
  }

  50% {
    transform: translateX(20px);
  }

  100% {
    transform: translateX(0);
  }
}

.__UIV_SCOPE__ .round {
  width: 6px;
  height: 6px;
  background: #3da9fc;
  border-radius: 50%;
}

.__UIV_SCOPE__ .line {
  display: flex;
  gap: 4px;
}

.__UIV_SCOPE__ .two {
  transform: translateX(10px);
}

.__UIV_SCOPE__ .three {
  transform: translateX(20px);
}

.__UIV_SCOPE__ .four {
  transform: translateX(30px);
}

.__UIV_SCOPE__ .five {
  transform: translateX(20px);
}

.__UIV_SCOPE__ .six {
  transform: translateX(10px);
}
